import requests

API_URL = "https://api.zdx.example.com/graphql"

session = requests.Session()  # keep-alive: reuse TLS connection
session.headers.update({
    "Authorization": "Bearer <token>",
    "Content-Type": "application/json",
    "Accept-Encoding": "gzip",   # mandatory
})

query = """
query ListDevices($from: DateTime!, $to: DateTime!, $first: Int!, $after: String) {
  ZDX {
    devices(first: $first, after: $after, time_range: {from: $from, to: $to}) {
      total_count
      page_info { has_next_page end_cursor }
      edges { node { id { value } name { value } profile { os_name zdx_version } } }
    }
  }
}
"""

resp = session.post(API_URL, json={
    "query": query,
    # one-hour window: API aggregates metrics over the whole range requested
    "variables": {"from": "2026-09-09T00:00:00Z", "to": "2026-09-09T01:00:00Z",
                  "first": 1000, "after": None},
})
resp.raise_for_status()
data = resp.json()                 # already decompressed by requests
if data.get("errors"):             # partial errors arrive on HTTP 200
    raise RuntimeError(data["errors"])

# verify compression actually happened (optional sanity check)
assert resp.headers.get("Content-Encoding") == "gzip"
